{"content":":root {
  color-scheme: dark;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: #080b12;
  color: #e5e7eb;
}

* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  background:
    radial-gradient(circle at 8% 0%, rgba(250, 204, 21, 0.18), transparent 28rem),
    radial-gradient(circle at 90% 8%, rgba(59, 130, 246, 0.22), transparent 30rem),
    linear-gradient(135deg, #070a12 0%, #111827 58%, #171717 100%);
}
button, input { font: inherit; }
.shell { width: min(1180px, calc(100% - 28px)); margin: 0 auto; padding: 28px 0; }
.panel {
  border: 1px solid rgba(148, 163, 184, 0.22);
  background: rgba(15, 23, 42, 0.82);
  box-shadow: 0 24px 90px rgba(0, 0, 0, 0.42);
  backdrop-filter: blur(18px);
  border-radius: 28px;
  padding: 24px;
}
.hero { display: grid; grid-template-columns: 1.35fr 0.65fr; gap: 22px; align-items: center; margin-bottom: 22px; }
.eyebrow { margin: 0 0 10px; color: #facc15; font-size: 0.76rem; font-weight: 900; letter-spacing: 0.18em; text-transform: uppercase; }
h1, h2, h3, p { margin-top: 0; }
h1 { font-size: clamp(2.45rem, 7vw, 5.4rem); line-height: 0.9; letter-spacing: -0.07em; margin-bottom: 18px; }
h2 { font-size: clamp(1.45rem, 3vw, 2.15rem); margin-bottom: 14px; }
h3 { margin-bottom: 10px; }
.lede { color: #bac7d6; line-height: 1.72; font-size: 1.05rem; max-width: 70ch; margin-bottom: 0; }
.mission-box { border: 1px solid rgba(250, 204, 21, 0.28); border-radius: 22px; padding: 20px; background: rgba(250, 204, 21, 0.08); }
.mission-box strong, .mission-box span { display: block; }
.mission-box strong { font-size: 1.4rem; margin-bottom: 8px; }
.mission-box span { color: #d1d5db; line-height: 1.5; }
.grid { display: grid; grid-template-columns: 0.9fr 1.1fr; gap: 22px; align-items: start; }
.field { display: grid; gap: 8px; margin: 16px 0; }
.field span { color: #dbeafe; font-weight: 800; font-size: 0.9rem; }
input[type="text"], .field input {
  width: 100%;
  border: 1px solid rgba(148, 163, 184, 0.28);
  border-radius: 18px;
  background: rgba(2, 6, 23, 0.62);
  color: #f9fafb;
  outline: none;
  padding: 15px 16px;
}
input:focus { border-color: #facc15; box-shadow: 0 0 0 4px rgba(250, 204, 21, 0.11); }
button {
  border: 0;
  border-radius: 999px;
  background: #facc15;
  color: #111827;
  cursor: pointer;
  font-weight: 950;
  padding: 13px 18px;
  transition: transform 0.15s ease, opacity 0.15s ease;
}
button:hover { transform: translateY(-1px); }
button:disabled { opacity: 0.45; cursor: not-allowed; }
.dropzone {
  display: grid;
  gap: 8px;
  place-items: center;
  text-align: center;
  min-height: 155px;
  border: 1px dashed rgba(250, 204, 21, 0.45);
  border-radius: 24px;
  background: rgba(2, 6, 23, 0.42);
  cursor: pointer;
  padding: 18px;
  margin-bottom: 16px;
}
.dropzone input { display: none; }
.dropzone span { font-weight: 950; font-size: 1.25rem; }
.dropzone small, .muted { color: #94a3b8; line-height: 1.5; }
.error { margin: 14px 0 0; color: #fecdd3; background: rgba(244, 63, 94, 0.1); border: 1px solid rgba(244, 63, 94, 0.25); border-radius: 16px; padding: 12px; }
details { margin-top: 14px; color: #cbd5e1; }
pre { white-space: pre-wrap; color: #94a3b8; background: rgba(2, 6, 23, 0.45); border-radius: 14px; padding: 12px; max-height: 160px; overflow: auto; }
.matches { margin-top: 24px; display: grid; gap: 10px; }
.match {
  width: 100%;
  text-align: left;
  border-radius: 18px;
  background: rgba(30, 41, 59, 0.72);
  color: #e5e7eb;
  padding: 14px;
  border: 1px solid rgba(148, 163, 184, 0.16);
}
.match.active { border-color: #facc15; background: rgba(250, 204, 21, 0.12); }
.match span, .match small { display: block; }
.match span { font-weight: 900; }
.match small { color: #94a3b8; margin-top: 4px; }
.empty { display: grid; place-items: center; min-height: 420px; color: #94a3b8; }
.card-head { display: grid; grid-template-columns: 160px 1fr; gap: 20px; align-items: start; }
.card-head img { width: 100%; border-radius: 14px; box-shadow: 0 18px 40px rgba(0,0,0,0.35); }
.card-head p { color: #aebdd0; line-height: 1.5; }
.estimate { display: inline-grid; gap: 2px; border: 1px solid rgba(34, 197, 94, 0.28); background: rgba(34, 197, 94, 0.1); padding: 13px 16px; border-radius: 18px; }
.estimate span { color: #bbf7d0; text-transform: uppercase; letter-spacing: 0.12em; font-size: 0.7rem; font-weight: 900; }
.estimate strong { color: #dcfce7; font-size: 1.8rem; }
.price-table { display: grid; gap: 10px; margin-top: 22px; }
.price-row {
  display: grid;
  grid-template-columns: 1fr 1.2fr auto;
  gap: 12px;
  align-items: center;
  text-decoration: none;
  color: #e5e7eb;
  border: 1px solid rgba(148, 163, 184, 0.16);
  background: rgba(2, 6, 23, 0.38);
  border-radius: 16px;
  padding: 13px 14px;
}
.price-row span { font-weight: 950; }
.price-row em { color: #94a3b8; font-style: normal; }
.price-row strong { color: #fef3c7; }
.operator-note, .disclaimer { margin-top: 22px; color: #bac7d6; line-height: 1.68; }
.operator-note { border-left: 3px solid #facc15; padding-left: 14px; }
.disclaimer strong, .operator-note strong { color: #f9fafb; }
@media (max-width: 860px) {
  .shell { width: min(100% - 20px, 720px); padding: 16px 0; }
  .hero, .grid, .card-head { grid-template-columns: 1fr; }
  .panel { border-radius: 22px; padding: 18px; }
  .card-head img { max-width: 220px; }
  .price-row { grid-template-columns: 1fr; }
}
